#r "nuget: FsHttp"
open FsHttp

let getSnorlax () =
    http {
        GET "https://example.com/pokemon/snorlax"
    }

let postBerry =
    http {
        POST "https://example.com/berry"
        header "X-Berry" (
            http {
                GET "https://example.com/berry/1"
            }
            |> string
        )
    }

let oneLine = http { GET "https://example.com/"; header "X-Inner" (string (http { GET "https://example.com/inner" })) }
